import java.util.Scanner;

public class Main {
    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);
        String inputStr = scanner.next();
        char initialChar = inputStr.charAt(0);
        String rest = inputStr.substring(1);
        int atIdx = rest.indexOf("at");
        if (atIdx != -1) {
            rest = rest.substring(0, atIdx) + "@" + rest.substring(atIdx + 2);
        }
        int dotIdx;
        while ((dotIdx = rest.indexOf("dot")) != -1 && dotIdx != rest.length() - 3) {
            rest = rest.substring(0, dotIdx) + "." + rest.substring(dotIdx + 3);
        }
        System.out.print(initialChar + rest);
        scanner.close();
    }
}
